import sys; sys.path.insert(0, __import__("pathlib").Path(__file__).resolve().parents[1].as_posix())
from explications import *

ENTREES = [
    ("## 🗝️ Vocabulaire", 'fin', apropos("Les cartes électroniques de ton téléphone sont des **plaques vertes** couvertes de fines **lignes de cuivre**. Comment fabrique-t-on ces lignes ?", "On part d'une plaque **entièrement recouverte de cuivre**, puis on **enlève le cuivre inutile** avec un produit chimique. Il ne reste que les **pistes** dessinées par le schéma.\n\nDans cette séance, tu apprends à **fabriquer un circuit imprimé simple face**, à **percer** les trous et à **contrôler** sa qualité. Attention : on manipule des **produits chimiques**, la sécurité est **obligatoire**.")),
    ("## 1.", 'fin', clair("Un PCB simple face est un **sandwich** :\n\n- le **support** isolant (en fibre de verre et résine, appelé FR4) ;\n- une fine couche de **cuivre** (35 µm) ;\n- éventuellement un **vernis** qui protège les pistes.\n\nLe cuivre sert de **fils** : les **pistes** relient les composants. Les composants se posent d'un côté et se soudent **de l'autre côté**.") + "\n" + verifie(
        ("À quoi servent les pistes d'un PCB ?", "Elles jouent le rôle de **fils** : elles relient les composants entre eux."),
        ("De quoi est fait le support d'un PCB ?", "D'un matériau **isolant** (FR4) recouvert de **cuivre**.")) ),
    ("## 2.", 'fin', clair("La fabrication suit **8 étapes** : **1.** dessiner le schéma et le routage, **2.** imprimer le calque (typon), **3.** le transférer sur la plaque, **4.** révéler, **5.** **graver** (le chlorure ferrique mange le cuivre non protégé), **6.** rincer et neutraliser, **7.** nettoyer, **8.** percer.\n\nLe **toner** ou la résine **protège** le cuivre qu'on veut garder : le produit n'attaque que le cuivre **nu**.") + "\n" + erreurs("Laisser la plaque trop longtemps dans le bain : sur-gravure, les pistes deviennent trop fines.", "Ne pas assez graver : des **ponts de cuivre** restent entre les pistes (court-circuits).") + "\n" + verifie(
        ("Pourquoi le cuivre protégé par le toner n'est-il pas attaqué ?", "Parce que le toner est **résistant** au chlorure ferrique : le produit ne dissout que le cuivre **nu**."),
        ("Que risque-t-on avec une gravure trop courte ?", "Des **ponts de cuivre** (court-circuits) entre les pistes."),
        ("Cite deux équipements de sécurité à porter pendant la gravure.", "Des **gants** et des **lunettes** de protection (et une blouse, dans un local aéré).")) + "\n" + retenir("Le toner protège le cuivre ; le chlorure ferrique dissout le reste.", "Sécurité obligatoire : gants, lunettes, aération.")),
    ("## 3.", 'fin', clair("Le perçage se fait avec une **perceuse à colonne** et un **foret en carbure de tungstène** (très dur) de **0,8 à 1 mm** : vitesse **élevée**, avance **lente**. On perce **du côté cuivre**, la plaque posée sur une cale. Si on force, le foret **casse**.") + "\n" + verifie(
        ("Pourquoi utilise-t-on un foret en carbure de tungstène ?", "Parce que la fibre de verre est **très abrasive** : un foret ordinaire s'userait vite."),
        ("Comment doit-on régler la perceuse ?", "**Vitesse élevée**, **avance lente** : on ne force pas.")) ),
    ("## 4.", 'fin', clair("La norme **IPC-A-600** décrit comment **juger la qualité** d'un circuit imprimé. On regarde surtout : la **largeur des pistes**, l'**espacement** entre pistes, l'**anneau de cuivre** autour des trous, la **surface** des pistes et le **perçage**.\n\nL'**anneau de cuivre** est la couronne de cuivre qui reste autour d'un trou percé : il se calcule avec $\\dfrac{\\varnothing_{pastille} - \\varnothing_{trou}}{2}$.") + "\n" + verifie(
        ("Une pastille de 1,8 mm est percée avec un foret de 1,0 mm. Quelle est la largeur de l'anneau de cuivre ?", "$\\dfrac{1{,}8 - 1{,}0}{2} = 0{,}4\\,\\mathrm{mm}$."),
        ("Un trou est décalé et l'anneau est incomplet. Le circuit est-il conforme ?", "**Non** : l'anneau doit être complet pour une bonne soudure."),
        ("Pourquoi contrôle-t-on l'espacement entre deux pistes ?", "Pour détecter des **ponts de cuivre** qui créeraient un **court-circuit**.")) + "\n" + retenir("IPC-A-600 : largeur, espacement, anneau, surface, perçage.")),
    ("## 5.", 'fin', clair("Avant de souder, on **teste le circuit nu** au multimètre :\n\n- **continuité** d'une piste, d'un bout à l'autre : **BIP** attendu ;\n- **isolement** entre deux pistes voisines : **aucun bip**, résistance très grande ;\n- **continuité pastille – piste** : la pastille est bien reliée à sa piste.") + "\n" + verifie(
        ("On touche deux pistes voisines et le multimètre bipe. Que signifie-t-il ?", "Les pistes sont **reliées** par un pont de cuivre : c'est un **court-circuit** à corriger."),
        ("Que doit-on entendre en testant une piste d'un bout à l'autre ?", "Un **BIP** : la piste est continue.")) + "\n" + retenir("Piste : BIP. Entre deux pistes : silence.")),
]
